# coding=utf-8
from taf.cloud.lcmaas.provider import LCMaaSProvider


class LCMaaSConnection(object):
    def __init__(self, host, username, password, port=8443, lcmaas_version='lcmaas_v1', secure=True):
        self.lcmaas = LCMaaSProvider.create_lcmaas(host=host,
                                                   username=username,
                                                   password=password,
                                                   port=port,
                                                   lcmaas_version=lcmaas_version,
                                                   secure=secure)

    def get_dpps(self, group=None):
        """
        get all of the dpps information.

        :param str group: (Optional) group of dpp, default is None.
        :return list: list of DppInfoV1 object including dpp_name, dpp_group, dpp_status,
                      dpp_process, cnf_package, cnf_instance.
        """
        return self.lcmaas.get_dpps(group=group)

    def get_dpp_by_name(self, dpp_name):
        """
        Get dpp information by giving the dpp name.

        :param str dpp_name: dpp name
        :return object: DppInfoV1 object including dpp_name, dpp_group, dpp_status,
                        dpp_process, cnf_package, cnf_instance.
        """
        return self.lcmaas.get_dpp_by_name(dpp_name=dpp_name)

    def create_dpp(self, dpp_name, cnf_pkg_name, cnf_instance_name, vi_name, namespace,
                   chart_override_mapping=None, dpp_group=None):
        """
        create a DPP.

        :param str dpp_name: the name of DPP.
        :param str cnf_pkg_name: Name of the CNF package.
        :param str cnf_instance_name: Name of CNF instance.
        :param str vi_name: Name of VI.
        :param str namespace: Namespace scope for Dpp deploy.
        :param list chart_override_mapping: (Optional) a set of extra Values added to the chart, default is None, f.g:
                                           [{'aic-vdu-prerequisite-0.300.2580':'path of override yaml file'},
                                            {'aic-vdu-0.300.2580':'path of override yaml file'}]
        :param str dpp_group: (Optional) dpp group, default is None.
        :return object: DppInfoV1 object including dpp_name, dpp_group, dpp_status,
                        dpp_process, cnf_package, cnf_instance.
        """
        return self.lcmaas.create_dpp(dpp_name=dpp_name,
                                      cnf_pkg_name=cnf_pkg_name,
                                      cnf_instance_name=cnf_instance_name,
                                      vi_name=vi_name,
                                      namespace=namespace,
                                      chart_override_mapping=chart_override_mapping,
                                      dpp_group=dpp_group)

    def delete_dpp(self, dpp_name):
        """
        delete a given dpp.
        :param str dpp_name: Name of DPP.
        :return: None
        """
        return self.lcmaas.delete_dpp(dpp_name=dpp_name)

    def update_dpp(self, dpp_name, chart_override_mapping=None, cnfpkg_name=None):
        """
        update the helm chart override values of one dpp
        :param str dpp_name: dpp name.
        :param list chart_override_mapping: (Optional) a set of extra Values added to the chart, default is None, f.g:
                                            [{'aic-vdu-prerequisite-0.300.2580':'path of override yaml file'},
                                             {'aic-vdu-0.300.2580':'path of override yaml file'}]
        :param str cnfpkg_name: (Optional) Name of the CNF package.
        :return object: DppInfoV1 object including dpp_name, dpp_group, dpp_status,
                        dpp_process, cnf_package, cnf_instance.
        """
        return self.lcmaas.update_dpp(dpp_name, cnfpkg_name, chart_override_mapping)

    def get_vis(self, neat_name=None):
        """
        list information of all VIs。
        :param str neat_name: (Optional) name of Neat, default is None.
        :return list: list of VIInfoV1 object including name, kube_config, image_registry
        """
        return self.lcmaas.get_vis(neat_name=neat_name)

    def delete_vi(self, vi_name):
        """
        delete a VI with given name.

        :param str vi_name: the VI name needs to be deleted.
        :return: None
        """
        return self.lcmaas.delete_vi(vi_name=vi_name)

    def create_neat(self, name, mgmt_url, auth_url, username, password, client_id, ca_certs=None):
        """
        add a NEAT.

        :param str name: the NEAT entity name.
        :param str mgmt_url: NEAT API url.
        :param str auth_url: API URL Providing Authentication Services by NADCM
        :param str username: username of NEAT to fetch access token from NADCM.
        :param str password: password of NEAT to fetch access token from NADCM.
        :param str client_id: client id of NEAT to fetch access token from NADCM.
        :param str ca_certs: (Optional) Certificate(s) content with PEM format, default is None.
        :return dict: NeatInfoV1 object
        """
        return self.lcmaas.create_neat(name=name,
                                       mgmt_url=mgmt_url,
                                       auth_url=auth_url,
                                       username=username,
                                       password=password,
                                       client_id=client_id,
                                       ca_certs=ca_certs)

    def get_neat_info_by_name(self, neat_name):
        """
        get NEAT information by giving the NEAT name.

        :param str neat_name: the NEAT entity name.
        :return dict: NeatInfoV1 object
        """
        return self.lcmaas.get_neat_info_by_name(neat_name=neat_name)

    def get_neats_info(self):
        """
        get all of the NEATs information.

        :return list: list of NeatInfoV1 object
        """
        return self.lcmaas.get_neats_info()

    def update_vi(self, vi_name, image_registry_addr, image_registry_user=None, image_registry_pwd=None,
                  image_registry_ca_certs=None, kubeconfig=None):
        """
        update a VI information.

        :param str vi_name: the name of VI.
        :param str image_registry_addr: the address of image registry address, like:
                                        default-route-openshift-image-registry.apps.tt15f-nh03.dyn.nesc.nokia.net
        :param str image_registry_user: (Optional) User for the image registry, default is None.
        :param str image_registry_pwd: (Optional) Password for the image registry, default is None.
        :param str image_registry_ca_certs:(Optional)  Certificate Content With PEM Format, default is None.
        :param str kubeconfig: (Optional) kubeconfig content.
        :return dict: VIInfoV1 object
        """
        return self.lcmaas.update_vi(vi_name=vi_name,
                                     image_registry_addr=image_registry_addr,
                                     image_registry_user=image_registry_user,
                                     image_registry_pwd=image_registry_pwd,
                                     image_registry_ca_certs=image_registry_ca_certs,
                                     kubeconfig=kubeconfig)

    def install_certs(self, peer_type, peer_name, cert_content):
        """
        install certificate(s)

        :param str peer_name: the peer name, like VI name or NEAT name.
        :param str peer_type: Peer type for which the certificate is installed, can be one of [ NEAT, VI, SELF ].
        :param str cert_content: Certificate Content With PEM Format
        :return list: list of CertInfoV1 object
        """
        return self.lcmaas.install_certs(peer_type=peer_type, peer_name=peer_name, cert_content=cert_content)

    def create_cnf_package(self, cnf_pkg_name, cnf_pkg_url):
        """
        Create a CNF package.

        :param str cnf_pkg_name: Name of the CNF package, it should satisfy the pattern: ^[A-Za-z][A-Za-z0-9_.]*$
        :param str cnf_pkg_url: URL of CNF package from where it could downloaded.
        :return dict: CnfPkgInfoV1 object
        """
        return self.lcmaas.create_cnf_package(cnf_pkg_name=cnf_pkg_name, cnf_pkg_url=cnf_pkg_url)

    def get_cnf_package_info_by_name(self, cnf_pkg_name):
        """
        get CNF package information with given name.

        :param str cnf_pkg_name: Name of the CNF package
        :return dict: CnfPkgInfoV1 object
        """
        return self.lcmaas.get_cnf_package_info_by_name(cnf_pkg_name=cnf_pkg_name)

    def get_cnf_packages_info(self):
        """
        get all of CNF package information.

        :return list: list of CnfPkgInfoV1 object
        """
        return self.lcmaas.get_cnf_packages_info()

    def validate_dpp(self, dpp_name=None, dpp_group=None):
        """
        Validate a DPP or a DPP group. Valid means VI should be accessible, CNF package is available,
        helm charts inside CNF package is OK. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.validate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    def onboard_container_images_to_vi(self, dpp_name=None, dpp_group=None):
        """
        Onboard container images of DPP(s) to VI. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.onboard_container_images_to_vi(dpp_name=dpp_name, dpp_group=dpp_group)

    def instantiate_dpp(self, dpp_name=None, dpp_group=None):
        """
        Instantiate CNF of DPP or CNFs of DPP group. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.instantiate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    def terminate_dpp(self, dpp_name=None, dpp_group=None):
        """
        terminate CNF of DPP or CNFs of DPP group. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.terminate_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    def delete_cnf_pkg(self, cnf_pkg_name):
        """
        Delete a CNF package. One of the parameters - dpp_name or dpp_group must be given.

        :param str cnf_pkg_name: CNF package name.
        :return: None
        """
        return self.lcmaas.delete_cnf_pkg(cnf_pkg_name=cnf_pkg_name)

    def upgrade_dpp(self, dpp_name=None, dpp_group=None):
        """
        Upgrade DPP or DPP group. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.upgrade_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    def rollback_dpp(self, dpp_name=None, dpp_group=None):
        """
        Rollback DPP or DPP group. One of the parameters - dpp_name or dpp_group must be given.

        :param str dpp_name: (optional) the name of DPP. dpp_group must be given if dpp_name is None.
        :param str dpp_group: (optional) the name of DPP group. dpp_name must be given if dpp_group is None.
        :return: None
        """
        return self.lcmaas.rollback_dpp(dpp_name=dpp_name, dpp_group=dpp_group)

    def create_vi(self, vi_name, kube_config, image_registry_addr, image_registry_user, image_registry_pwd,
                  image_registry_ca_certs):
        """
        Create VI

        :param str vi_name: the name of VI.
        :param str kube_config: kubeconfig content.
        :param str image_registry_addr: the address of image registry address, like:
                                        default-route-openshift-image-registry.apps.tt15f-nh03.dyn.nesc.nokia.net
        :param str image_registry_user: User for the image registry, default is None.
        :param str image_registry_pwd: Password for the image registry, default is None.
        :param str image_registry_ca_certs: Certificate Content With PEM Format, default is None.
        :return: it returns a ViOut object
        """
        return self.lcmaas.create_vi(vi_name=vi_name, kube_config=kube_config,
                                     image_registry_addr=image_registry_addr,
                                     image_registry_user=image_registry_user,
                                     image_registry_pwd=image_registry_pwd,
                                     image_registry_ca_certs=image_registry_ca_certs)
